using Microsoft.EntityFrameworkCore;using MySqlConnector;using HealthPlatform.Persistence;using HealthPlatform.Application;using HealthPlatform.Domain.Patient;using HealthPlatform.Domain.Identity;using HealthPlatform.Domain.Consent;using HealthPlatform.Domain.Audit;using HealthPlatform.Infrastructure;using HealthPlatform.Contracts;using System.Security.Cryptography;
namespace HealthPlatform.IntegrationTests;
public sealed class Actor:ICurrentActor {public Guid TenantId{get;set;}=Guid.NewGuid();public string Subject{get;set;}="patient";public bool IsPatient{get;set;}=true;public bool IsPractitioner{get;set;}public bool RecentMfa{get;set;}=true;public string CorrelationId=>"integration";}
public sealed class MySqlTests:IAsyncLifetime {
 readonly Actor actor=new();string connection="";readonly string database="hp_test_"+Guid.NewGuid().ToString("N");
 HealthDbContext Db(Actor? a=null)=>new(new DbContextOptionsBuilder<HealthDbContext>().UseMySql(connection,new MySqlServerVersion(new Version(8,0,36))).Options,a??actor);
 public async Task InitializeAsync(){var cs=Environment.GetEnvironmentVariable("HEALTH_TEST_MYSQL")??"server=localhost;port=3306;user=root;password=";var b=new MySqlConnectionStringBuilder(cs){Database=database};connection=b.ConnectionString;await using var db=Db();await db.Database.MigrateAsync();}
 public async Task DisposeAsync(){await using var db=Db();await db.Database.EnsureDeletedAsync();}
 Handlers Handler(HealthDbContext db,QrCodeService crypto){var repo=new HealthRepository(db);return new(repo,new QrChallengeRepository(db),actor,new AccessService(repo,actor,TimeProvider.System),crypto,crypto,TimeProvider.System,new AutoMapper.MapperConfiguration(c=>c.AddProfile<PatientMapping>(),Microsoft.Extensions.Logging.Abstractions.NullLoggerFactory.Instance).CreateMapper());}
 [Fact]public async Task FullConsentLifecycle(){using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256);using var crypto=new QrCodeService(key.ExportPkcs8PrivateKeyPem(),"test");await using var db=Db();var h=Handler(db,crypto);var p=await h.Handle(new RegisterPatient(new("Synthetic","Patient",new(1990,1,1))),default);var qr=await h.Handle(new IssueQr(p.Id,new()),default);var org=new Organization(actor.TenantId,"Synthetic clinic","CA-QC");db.Add(org);db.Add(new Practitioner(actor.TenantId,"doctor","Verified professional",org.Id,DateTime.UtcNow.AddDays(30),true));await db.SaveChangesAsync();actor.Subject="doctor";actor.IsPatient=false;actor.IsPractitioner=true;
 await Assert.ThrowsAsync<AccessDenied>(()=>h.Handle(new GetPatient(p.Id),default));
 var request=await h.Handle(new ScanQr(new(qr.QrPayload)),default);actor.Subject="patient";actor.IsPatient=true;actor.IsPractitioner=false;
 var decision=await h.Handle(new DecideAccess(request,new(true)),default);Assert.NotNull(decision.GrantId);actor.Subject="doctor";actor.IsPatient=false;actor.IsPractitioner=true;Assert.Equal(p.Id,(await h.Handle(new GetPatient(p.Id),default)).Id);
 actor.Subject="patient";actor.IsPatient=true;actor.IsPractitioner=false;await h.Handle(new RevokeGrant(decision.GrantId!.Value),default);actor.Subject="doctor";actor.IsPatient=false;actor.IsPractitioner=true;await Assert.ThrowsAsync<AccessDenied>(()=>h.Handle(new GetPatient(p.Id),default));Assert.True(await db.Audit.CountAsync()>=5);Assert.Equal(3,await db.Outbox.CountAsync());}
 [Fact]public async Task TenantIsolationAndWriteGuard(){await using var db=Db();var p=new PatientProfile(actor.TenantId,"patient",new("Test","Only"),new(1990,1,1));db.Add(p);await db.SaveChangesAsync();await using var other=Db(new Actor());Assert.Empty(await other.Patients.ToListAsync());other.Add(new PatientProfile(actor.TenantId,"other",new("X","Y"),new(1990,1,1)));await Assert.ThrowsAsync<AccessDenied>(()=>other.SaveChangesAsync());}
 [Fact]public async Task ConcurrentQrConsumptionHasOneWinner(){Guid id;await using(var db=Db()){var p=new PatientProfile(actor.TenantId,"patient",new("Test","Only"),new(1990,1,1));db.Add(p);var q=new QrChallenge(Guid.NewGuid(),actor.TenantId,p.Id,"nonce",DateTime.UtcNow.AddMinutes(5),DataScope.Profile);db.Add(q);await db.SaveChangesAsync();id=q.Id;}await using var first=Db();await using var second=Db();var a=await first.Challenges.SingleAsync(x=>x.Id==id);var b=await second.Challenges.SingleAsync(x=>x.Id==id);a.Consume(DateTime.UtcNow);b.Consume(DateTime.UtcNow);await first.SaveChangesAsync();await Assert.ThrowsAsync<DbUpdateConcurrencyException>(()=>second.SaveChangesAsync());}
 [Fact]public async Task AuditIsAppendOnly(){await using var db=Db();var entry=new AuditEntry(actor.TenantId,null,"actor","test","permit","trace");db.Add(entry);await db.SaveChangesAsync();db.Remove(entry);await Assert.ThrowsAsync<InvalidOperationException>(()=>db.SaveChangesAsync());}
 [Fact]public async Task MigrationsHaveNoPendingModelChanges(){await using var db=Db();Assert.False(db.Database.HasPendingModelChanges());Assert.NotEmpty(await db.Database.GetAppliedMigrationsAsync());}
}
